#!/usr/bin/env bash
# Documentation : « Étude de cas » — le moteur des tutoriels interactifs, en trois chapitres ; Qualité à jour.
# Prérequis : apply-fix-tours.sh et apply-docs-infra.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-etude-de-cas.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/etude-de-cas/lancer-verifier-ecrire.mdx" 2>/dev/null | grep -qF "Fin du parcours"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "import { TourStartButton }" "apps/web/src/mdx-components.tsx" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-tours.sh"; exit 1; }
grep -qF "Ordonner les couches du plus stable au plus changeant" "apps/web/content/docs/dev/infrastructure/l-image-docker.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-infra.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/contenu/le-rendu-serveur.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx")
EXPECT=("6375529a04ef:apps/web/content/docs/dev/contenu/le-rendu-serveur.mdx" "172e50e3a417:apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "c2a4ae70cea1:apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "9be389dd0fbf:apps/web/content/docs/dev/qualite/les-gardes-maison.mdx" "d2b6b2a1b376:apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/content/docs/dev/etude-de-cas/lancer-verifier-ecrire.mdx" "apps/web/content/docs/dev/etude-de-cas/le-moteur.mdx" "apps/web/content/docs/dev/etude-de-cas/un-tutoriel-en-donnees.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/etude-de-cas" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Fin du parcours" "apps/web/content/docs/dev/etude-de-cas/lancer-verifier-ecrire.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/etude-de-cas"
base64 -d > "apps/web/content/docs/dev/etude-de-cas/lancer-verifier-ecrire.mdx" <<'B64'
