# Table de l'index : ligne « Étude de cas », quel que soit son texte actuel.
F=apps/web/content/docs/dev/index.mdx
if ! git diff --quiet HEAD -- "$F"; then echo "❌ $F a des modifications non commitées"; restore; exit 1; fi
MODIFIED+=("$F")
python3 - "$F" <<'PY2'
import re, sys
p = sys.argv[1]; s = open(p, encoding="utf-8").read()
new = "[\"Étude de cas\",\"Le moteur des tutoriels interactifs, en trois chapitres : un tutoriel en données (des étapes typées, un contrat de nom data-tour, une garde qui le tient) ; le moteur (un état qui traverse les pages, un voile percé qui suit sa cible, quatre façons de passer une étape, le clavier) ; lancer, vérifier, écrire (deux portes d’entrée, un test qui suit le tuto et ce qu’il a trouvé, la recette d’un nouveau tuto).\",\"rédigée\"]"
s2, n = re.subn(r'\["Étude de cas","[^"]*","[^"]*"\]', lambda m: new, s)
assert n == 1, n
open(p, "w", encoding="utf-8").write(s2)
PY2
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
docs(etude-de-cas): le moteur des tutoriels interactifs, en trois chapitres

- Un tutoriel, en données : les types pas à pas, le premier tuto, le registre, le contrat data-tour
  et la garde qui le tient
- Le moteur : le store (sessionStorage, useSyncExternalStore), le fournisseur, l'overlay (suivi de
  la cible, voile percé et bloqueurs, reconnaître l'action, le clavier, une étape perdue)
- Lancer, vérifier, écrire : les deux boutons, le test de bout en bout du tuto et ce qu'il a trouvé
  (PageRenderer dans le code du navigateur, server-only), la recette d'un nouveau tuto
- Qualité (gardes, tests), Contenu (rendu serveur), Démarrer et index à jour

